// Cloudflare Worker entry point (wrangler `main`). It sits in front of the Next.js app.
//
// Why: playing video through the Next.js server costs a lot of CPU, because every chunk is
// copied in JavaScript. On Cloudflare's free plan (10 ms CPU per request) that made seeking
// fail with "Worker exceeded resource limits". Here the video bytes are handed straight from
// Google Drive to the viewer, which Cloudflare does itself at almost no CPU cost.
// Everything else (pages, comments, admin) goes to the normal Next.js handler.
//
// @ts-expect-error generated by `opennextjs-cloudflare build`; not present when type-checking.
import handler from "./.open-next/worker.js";
import { fetchDriveMedia, mediaHeaders } from "./src/lib/drivestream";
import { authorizeStream } from "./src/lib/streamauth";

// OpenNext's worker exports these classes; Cloudflare needs them re-exported from the entry.
// @ts-expect-error generated file
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

async function streamVideo(request: Request): Promise<Response | null> {
  if (request.method !== "GET") return null;
  const match = /^\/api\/stream\/([^/]+)$/.exec(new URL(request.url).pathname);
  if (!match) return null;

  const token = new URL(request.url).searchParams.get("t");
  const auth = await authorizeStream(token);
  if (!auth || auth.videoId !== match[1]) return new Response("Forbidden", { status: 403 });
  if (auth.storage !== "drive") return null; // local dev files are served by the Next.js route

  const upstream = await fetchDriveMedia(auth.fileRef, request.headers.get("range"));
  return new Response(upstream.body, { status: upstream.status, headers: mediaHeaders(upstream, auth.mime) });
}

const worker = {
  async fetch(request: Request, env: Record<string, unknown>, ctx: unknown): Promise<Response> {
    // Make secrets visible as process.env before any of our code reads them.
    for (const [key, value] of Object.entries(env)) {
      if (typeof value === "string") process.env[key] = value;
    }
    return (await streamVideo(request)) ?? handler.fetch(request, env, ctx);
  },
};

export default worker;
